def preencher_data_conclusao(apps, schema_editor):
    """Encomendas já concluídas: a data em que foram entregues (ou a última alteração) — conta o prazo de devolução."""
    Encomenda = apps.get_model('app', 'Encomenda')
    Entrega = apps.get_model('app', 'Entrega')
    entregues = dict(Entrega.objects.filter(data_entrega__isnull=False).values_list('encomenda_id', 'data_entrega'))
    for e in Encomenda.objects.filter(status='concluido', data_conclusao__isnull=True).only('id', 'data_atualizacao'):
        Encomenda.objects.filter(pk=e.pk).update(data_conclusao=entregues.get(e.pk) or e.data_atualizacao)


